import{z as l,x as t,o as B,c as d,q as A,j as i,D as e,d as n,s as o,S as s,b as E}from"./chunks/framework.C8m1ZpeB.js";const u=JSON.parse('{"title":"DHS 过度自信模型","description":"","frontmatter":{"title":"DHS 过度自信模型","date":"2026-09-08T00:00:00.000Z","section":"econ"},"headers":[],"relativePath":"econ/dhs-overconfidence.md","filePath":"econ/dhs-overconfidence.md","lastUpdated":1791413859000}'),p={name:"econ/dhs-overconfidence.md"};function D(m,a,c,h,S,F){const r=t("Mermaid");return B(),d("div",null,[a[2]||(a[2]=A('<h1 id="dhs-过度自信模型" tabindex="-1">DHS 过度自信模型 <a class="header-anchor" href="#dhs-过度自信模型" aria-label="Permalink to &quot;DHS 过度自信模型&quot;">​</a></h1><div class="epigraph"><p>私人信号被当成过准，公开信号被低估；赢了归功自己，于是短期动量与长期反转不必借助体制切换。</p><footer>—— Daniel, Hirshleifer and Subrahmanyam, Investor Psychology and Security Market Under- and Overreactions, Journal of Finance, 1998</footer></div><p><a href="/econ/bsv-sentiment-model">上一课</a>用保守与代表性。本课缺口是另一微观零件：<a href="/econ/overconfidence">过度自信</a>加自我归因。同一组事实（不足与过度），不同的信息结构。不重写 BSV 的隐马尔可夫。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>投资者收到私人信号，高估其精度，价格对私有信息反应过度。随后的公开信息（盈余）被相对低估，价格慢慢纠正——公开信息路径上表现为反应不足（漂移）。若公开结果证实私人信号，自我归因进一步提高过度自信，过度再放大，之后更长的反转。Daniel、Hirshleifer 与 Subrahmanyam（1998）把这条写进均衡。缺口是对照 BSV：不是体制误设，是精度误设。</p><p><span class="marginnote">继续持有自己买入的股票、忽略公开空头证据，是同一机制的组合面。换手来自过度精确，已在 Odean 出现。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>两期或三期，风险资产，行为主体对私人信号方差低估。价格由他们的条件期望决定（或加有限套利）。比较静态：信息不对称越强、越难被公开信号取代的股票，过度越严重。预测与 BSV 部分重叠（动量然后反转），但横截面强调估值不确定性、分析师分歧、换手——与过度自信更贴。</p>',8)),(B(),i(s,null,{default:e(()=>[o(r,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20OC%5B%22%E8%BF%87%E5%BA%A6%E7%B2%BE%E7%A1%AE%3A%20%E7%A7%81%E4%BA%BA%E4%BF%A1%E5%8F%B7%E8%BF%87%E5%87%86%22%5D%20--%3E%20OVER%5B%22%E5%AF%B9%E7%A7%81%E6%9C%89%E4%BF%A1%E6%81%AF%E5%8F%8D%E5%BA%94%E8%BF%87%E5%BA%A6%22%5D%0A%20%20PUB%5B%22%E5%85%AC%E5%BC%80%E4%BF%A1%E5%8F%B7%E8%A2%AB%E4%BD%8E%E4%BC%B0%22%5D%20--%3E%20UNDER%5B%22%E5%85%AC%E5%91%8A%E5%90%8E%E6%BC%82%E7%A7%BB%22%5D%0A%20%20ATTR%5B%22%E8%87%AA%E6%88%91%E5%BD%92%E5%9B%A0%22%5D%20--%3E%20AMP%5B%22%E8%AF%81%E5%AE%9E%E5%90%8E%E6%9B%B4%E8%BF%87%E5%BA%A6%2C%20%E7%84%B6%E5%90%8E%E5%8F%8D%E8%BD%AC%22%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[n(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=E("h2",{id:"机制",tabindex:"-1"},[n("机制 "),E("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=E("p",null,"机制是精度而非体制。贝叶斯若用错的 \\(\\sigma_{\\varepsilon}\\)，后验均值走得太远。公开信号的最优权重被压低，直到累积到足够强。自我归因让 \\(\\sigma_{\\varepsilon}\\) 的误设内生恶化。套利限制同样需要，否则理性者按正确精度交易会压回价格——SV 仍在后台。",-1)),a[5]||(a[5]=E("p",null,[E("span",{class:"marginnote"},"「低估信号方差」代入个数：若信号噪声的真实标准差是 2，投资者心里当成 1——同一句话被他当成两倍可信，后验就朝信号方向多走一倍。\\(\\sigma_{\\varepsilon}\\) 就是「这句话通常错多少」的度量，估小了就是过度自信。")],-1)),(B(),i(s,null,{default:e(()=>[o(r,{id:"mermaid-32",class:"mermaid",graph:"flowchart%20LR%0A%20%20PS%5B%22%E7%A7%81%E4%BA%BA%E4%BF%A1%E5%8F%B7%E5%88%B0%E8%BE%BE%22%5D%20--%3E%20OR%5B%22%E4%BB%B7%E6%A0%BC%E5%86%B2%E8%BF%87%E5%A4%B4%22%5D%0A%20%20PI%5B%22%E5%85%AC%E5%BC%80%E4%BF%A1%E6%81%AF%E9%99%86%E7%BB%AD%E5%88%B0%E8%BE%BE%22%5D%20--%3E%20DR%5B%22%E7%BC%93%E6%85%A2%E6%BC%82%E7%A7%BB%3A%20%E7%BB%A7%E7%BB%AD%E6%9C%9D%E7%A7%81%E4%BA%BA%E4%BF%A1%E5%8F%B7%E6%96%B9%E5%90%91%22%5D%0A%20%20CONF%5B%22%E7%BB%93%E6%9E%9C%E8%AF%81%E5%AE%9E%E7%A7%81%E4%BA%BA%E4%BF%A1%E5%8F%B7%22%5D%20--%3E%20SA%5B%22%E8%87%AA%E6%88%91%E5%BD%92%E5%9B%A0%3A%20%E6%9B%B4%E8%87%AA%E4%BF%A1%22%5D%0A%20%20SA%20--%3E%20MORE%5B%22%E8%BF%87%E5%BA%A6%E5%86%8D%E6%94%BE%E5%A4%A7%22%5D%0A%20%20CUM%5B%22%E5%85%AC%E5%BC%80%E8%AF%81%E6%8D%AE%E7%B4%AF%E7%A7%AF%E5%88%B0%E8%B6%B3%E5%A4%9F%E5%BC%BA%22%5D%20--%3E%20REV%5B%22%E9%95%BF%E6%9C%9F%E5%8F%8D%E8%BD%AC%22%5D%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[n(" Loading... ",-1)])]),_:1})),a[6]||(a[6]=A('<p>与家庭参与：过度自信可以提高参与（人以为自己能选股），同时伤害净收益。本课市场模型用的是代表性行为主体，不是家庭调查。</p><p>私人信号的精度被高估，等于把似然比放大，后验走得比贝叶斯远——对私有信息过度。公开盈余若被当成相对更噪，权重不足，价格在公告后继续朝私有信息所指的方向走，看起来像对公开信息反应不足。自我归因让精度误设随证实而恶化，长期必须纠正时就反转。横截面上，估值不确定、分析师分歧大的股票更符合精度故事，盈余路径更符合 BSV，本课不赛马。</p><p><span class="marginnote">自我归因可以类比赌球：赢了归功自己眼光准，输了怪裁判——赢的记在自己头上，输的推给外界。连续几次被证实后，人会越押越大，直到现实算总账。模型里这就是 \\(\\sigma_{\\varepsilon}\\) 的误设随成功交易而加深。</span></p><p><span class="marginnote">初学者容易把「反应过度」读成「涨太多马上就跌」；DHS 的时序是三段：先冲过头，再沿原方向漂移一段，最后才反转。把三段压成一句话，就预测不出公告后漂移这个可检验的事实。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>DHS 与 BSV 不是赛马课。经验上常用横截面区分：分析师覆盖、换手、估值不确定更支持 DHS；盈余序列路径更支持 BSV。两者都可以在套利限制下存活。本课不估计。也不把做市商的信息优势写成过度自信。</p><p>后课默认：Hong–Stein 第三条路不靠错误精度，而靠信息在人群中慢慢扩散。</p><p>精度误设：私有信号过准则过度，公开信号被当成更噪则漂移。自我归因让误设随证实恶化。</p><p>与 BSV 事实重叠、横截面线索不同：分歧与换手更贴 DHS。</p><p><span class="marginnote">DHS 与 BSV 并列，不在本课赛马；横截面线索才分叉。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>DHS：过度精确造成对私有信息过度，对公开信息不足。</li><li>自我归因使过度自信不被证伪，放大动量后的反转。</li><li>与 BSV 分工：精度对体制；事实重叠，横截面线索不同。</li><li>不重写自我归因的微观定义。</li><li>套利限制仍在后台，否则正确精度会压回价格。</li><li>出处：Daniel, Hirshleifer and Subrahmanyam, <em>JF</em> 1998。</li></ul>',12))])}const C=l(p,[["render",D]]);export{u as __pageData,C as default};
